import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.B7PviQjB.js";const n="/docs/images/notes/index-split-view.png",u=JSON.parse('{"title":"Notes","description":"A note is a Markdown document you write with a live preview, together with your team in real time.","frontmatter":{"title":"Notes","description":"A note is a Markdown document you write with a live preview, together with your team in real time.","type":"overview"},"headers":[],"relativePath":"notes/index.md","filePath":"notes/index.md"}'),i={name:"notes/index.md"};function s(l,e,d,h,c,m){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h1><p>A note is a Markdown document you write with a live preview, together with your team in real time.</p><p>Use it to:</p><ul><li>Take meeting notes and checklists that everyone edits at once</li><li>Draft runbooks, release notes, and specs with code blocks, tables, and diagrams</li><li>Keep a shared scratchpad in plain Markdown, without page layout to manage</li></ul><p><img src="'+n+'" alt="Note in Split view with Markdown source on the left, rendered preview on the right, and the toolbar above"></p><h2 id="get-started" tabindex="-1">Get started <a class="header-anchor" href="#get-started" aria-label="Permalink to &quot;Get started&quot;">​</a></h2><ol><li>In your workspace, click <strong>New</strong>, then select <strong>New note</strong>. A note named <strong>New Note</strong> opens.</li><li>Type Markdown in the source pane, or use the toolbar to format text. See <a href="/docs/notes/write-and-format.html">Write and format</a>.</li><li>Click <strong>Share</strong> in the top right to invite your team. See <a href="/docs/collaborate/share.html">Share a document</a>.</li></ol><p>Click the note&#39;s title in the header to rename it. Changes save automatically.</p><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><p><strong>Write and format</strong></p><ul><li><a href="/docs/notes/write-and-format.html#set-a-heading">Add headings, bold text, links, lists, and checklists</a></li><li><a href="/docs/notes/write-and-format.html#insert-a-quote-code-block-foldout-or-table">Insert quotes, code blocks, foldouts, tables, and images</a></li><li><a href="/docs/notes/write-and-format.html#tick-tasks-in-the-preview">Tick tasks in the preview</a></li><li><a href="/docs/notes/write-and-format.html#find-and-replace-text">Find and replace text</a></li></ul><p><strong>Set up the editor</strong></p><ul><li><a href="/docs/notes/write-and-format.html#choose-a-layout">Switch between Editor, Split, and Preview</a></li><li><a href="/docs/notes/write-and-format.html#see-who-wrote-each-line">See who wrote each line</a></li><li><a href="/docs/notes/write-and-format.html#use-vim-keys">Use Vim keys</a></li></ul><p><strong>Work with others</strong></p><ul><li><a href="/docs/collaborate/edit-together.html">Edit together and see collaborators&#39; cursors</a></li><li><a href="/docs/collaborate/version-history.html">Browse and restore earlier versions</a></li><li><a href="/docs/collaborate/templates.html">Start from a template or publish one</a></li></ul><h2 id="on-a-phone" tabindex="-1">On a phone <a class="header-anchor" href="#on-a-phone" aria-label="Permalink to &quot;On a phone&quot;">​</a></h2><p>On a screen narrower than 768 pixels, a note has no Split view. One <strong>Preview</strong> button switches between the source and the rendered note. The toolbar keeps undo, redo, the text style, bold, and italic, and moves the rest into the ⋮ menu (<strong>More formatting options</strong>). See <a href="/docs/start/phone.html">Use Wafflebase on a phone</a>.</p><h2 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to &quot;Reference&quot;">​</a></h2><ul><li><a href="/docs/notes/markdown-reference.html">Markdown reference</a>: every syntax the preview renders, including math, diagrams, and the HTML it allows</li><li><a href="/docs/notes/keyboard-shortcuts.html">Keyboard shortcuts</a>: formatting, editing, and find keys</li></ul><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/docs/notes/write-and-format.html">Write and format</a> to learn the toolbar.</li><li><a href="/docs/collaborate/share.html">Share a document</a> to give teammates edit or view access.</li><li><a href="/docs/developers/cli/documents.html#notes">CLI: documents and notes</a> to import or export a note as a <code>.md</code> file.</li></ul>',21)])])}const f=t(i,[["render",s]]);export{u as __pageData,f as default};
